SELECT s.stay_id, p.gender, p.age, r.rr_mean, r.rr_median, r.rr_iqr, COUNT(r.rr_mean) AS n FROM physionet-data.mimiciv_3_1_icu.icustays s JOIN physionet-data.mimiciv_3_1_hosp.patients p ON s.subject_id = p.subject_id JOIN (SELECT hadm_id, AVG(rr_value) AS rr_mean, MEDIAN(rr_value) AS rr_median, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY rr_value) - PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY rr_value) AS rr_iqr FROM physionet-data.mimiciv_3_1_icu.chartevents WHERE charttime BETWEEN 0 AND 48 AND itemid = 848077 GROUP BY hadm_id) AS r ON s.hadm_id = r.hadm_id WHERE p.gender = 'M' AND p.age BETWEEN 54 AND 64 AND r.rr_mean < 12 THEN '<12' WHEN r.rr_mean BETWEEN 12 AND 20 THEN '12–20' WHEN r.rr_mean BETWEEN 21 AND 29 THEN '21–29' ELSE '≥30' END AS rr_category, COUNT(r.rr_mean) AS n, AVG(r.rr_mean) AS rr_mean, MEDIAN(r.rr_mean) AS rr_median, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY r.rr_mean) - PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY r.rr_mean) AS rr_iqr FROM physionet-data.mimiciv_3_1_icu.chartevents WHERE charttime BETWEEN 0 AND 48 AND itemid = 848077 GROUP BY s.stay_id, p.gender, p.age;